 const changes=[];
 for(const entry of payload.entries){const before=read(entry.file),after=patch(before,entry);if(before===null&&after===null||before!==null&&after!==null&&before.equals(after))continue;changes.push({file:entry.file,beforeHash:before===null?null:hash(before),afterHash:hash(after),after:after.toString('base64')})}
